class TestNestedRepos(unittest.TestCase):
    """Group folders (Football/) and repos holding repos (SpecialRequests/) - found 2026-10-03."""

    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.dev = Path(self.tmp.name)
        for d in ("Group/SubA/.git", "Group/SubB/.git", "Host/.git", "Host/Inner/.git", "Host/docs",
                  "Plain/.git", "Loose"):
            (self.dev / d).mkdir(parents=True)
        (self.dev / "Loose/file.zip").write_text("x", encoding="utf-8")
        self.data = {"meta": {}, "ideas": [], "inbox": [], "projects": [
            row("Group", dev_folder="Group"), row("SubA", dev_folder="Group/SubA"),
            row("Host"), row("Plain"), row("Loose")]}

    def tearDown(self):
        self.tmp.cleanup()

    def kinds(self, last="2026-10-01"):
        r = crosswalk.check(self.data, self.dev, None, since=dt.date(2026, 9, 12), last_commit=lambda p: last)
        return {(p["kind"], p["name"]) for p in r["problems"]}

    def test_sub_repos_without_rows_are_reported(self):
        k = self.kinds()
        self.assertIn(("unregistered_dev", "Group/SubB"), k)
        self.assertIn(("unregistered_dev", "Host/Inner"), k)
        self.assertNotIn(("unregistered_dev", "Group/SubA"), k)
        self.assertNotIn(("unregistered_dev", "Host/docs"), k)      # not a repo

    def test_folder_that_is_not_a_repo_is_flagged_but_a_group_is_not(self):
        k = self.kinds()
        self.assertIn(("not_a_repo", "Loose"), k)
        self.assertNotIn(("not_a_repo", "Group"), k)

    def test_stub_status_ignores_folders_without_their_own_git(self):
        # without its own .git, `git log` would read the enclosing DEV repo
        self.assertFalse(any(kind == "stub_status" and n in ("Group", "Loose") for kind, n in self.kinds()))

    def test_hidden_children_and_children_of_retired_rows_are_skipped(self):
        (self.dev / "Group/.claude/.git").mkdir(parents=True)
        (self.dev / "Old/Clone/.git").mkdir(parents=True)
        self.data["projects"].append(row("Old", status="archived"))
        k = self.kinds()
        self.assertNotIn(("unregistered_dev", "Group/.claude"), k)
        self.assertNotIn(("unregistered_dev", "Old/Clone"), k)

    def test_private_children_are_not_reported(self):
        # athlete-named child repos never get registry rows (portfolio.json is pushed + published)
        self.data["projects"][2]["private_children"] = True          # Host
        self.assertNotIn(("unregistered_dev", "Host/Inner"), self.kinds())

class TestStubMeansNoNextStep(unittest.TestCase):
    def status(self, text):
        d = Path(tempfile.mkdtemp())
        (d / "docs").mkdir()
        (d / "docs/STATUS.md").write_text(text, encoding="utf-8")
        return crosswalk._is_stub(d)

    def test_done_entries_without_a_next_step_still_count_as_stub(self):
        self.assertTrue(self.status("# STATUS\n\n## Done\n- 2026-10-02: decided X.\n\n## Next\n- \n\n## Open questions\n- \n"))

    def test_a_real_next_step_is_not_a_stub(self):
        self.assertFalse(self.status("# STATUS\n\n## Next\n- Run `python build.py`.\n"))

    def test_missing_status_is_a_stub(self):
        self.assertTrue(crosswalk._is_stub(Path(tempfile.mkdtemp())))


class TestFinishedWorkNeedsNoNext(unittest.TestCase):
    def test_done_rows_are_not_asked_for_a_next_step(self):
        dev = Path(tempfile.mkdtemp())
        (dev / "Fin/.git").mkdir(parents=True)
        data = {"projects": [row("Fin", status="done")]}
        r = crosswalk.check(data, dev, None, last_commit=lambda p: "2026-10-01")
        self.assertNotIn("stub_status", {p["kind"] for p in r["problems"]})

