FOLDER = "application/vnd.google-apps.folder"


def gws_list_folders(q: str, timeout: float = 30) -> list[dict]:
    """Every file matching Drive query `q` (id, name, parents), via the gws CLI."""
    files: list[dict] = []
    token = None
    while True:
        params = {"q": q, "fields": "nextPageToken,files(id,name,parents)", "pageSize": 1000}
        if token:
            params["pageToken"] = token
        r = subprocess.run(["gws", "drive", "files", "list", "--params", json.dumps(params)],
                           capture_output=True, text=True, timeout=timeout)
        if r.returncode != 0:
            raise RuntimeError(f"gws exit {r.returncode}: {r.stderr.strip()[-200:]}")
        page = json.loads(r.stdout)
        files += page.get("files", [])
        token = page.get("nextPageToken")
        if not token:
            return files


def drive_api_stages(list_folders=gws_list_folders) -> dict[str, set[str]]:
    """{stage: folder names} under 00_Primary_Storage_Drive/01_PROJECTS, as Drive itself sees it.

    Four gws calls (~10 s). Raises RuntimeError (or OSError/TimeoutExpired from gws) when it
    cannot answer; the caller reports that instead of trusting the mount silently.
    """
    def one(q: str, what: str) -> str:
        hits = list_folders(q)
        if len(hits) != 1:
            raise RuntimeError(f"expected one {what} folder on Drive, found {len(hits)}")
        return hits[0]["id"]

    live = f"mimeType = '{FOLDER}' and trashed = false"
    root = one(f"name = '00_Primary_Storage_Drive' and {live}", "00_Primary_Storage_Drive")
    projects = one(f"name = '01_PROJECTS' and '{root}' in parents and {live}", "01_PROJECTS")
    stage_ids = {f["id"]: f["name"] for f in list_folders(f"'{projects}' in parents and {live}")
                 if f["name"] in STAGE_DIRS}
    out: dict[str, set[str]] = {s: set() for s in STAGE_DIRS}
    if stage_ids:
        either = " or ".join(f"'{i}' in parents" for i in stage_ids)
        for f in list_folders(f"({either}) and {live}"):
            for p in f.get("parents", []):
                if p in stage_ids:
                    out[stage_ids[p]].add(f["name"])
    return out

